class Solution:
    def twoSum(self, nums: List[int], target: int) -> List[int]:
        seen = {}
        for i, x in enumerate(nums):
            need = target - x  # viz:need
            if need in seen:
                return [seen[need], i]  # viz:found
            seen[x] = i  # viz:store
        return []
